import{_ as o,r as s,o as p,c as l,e as a,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Определение опций - October CMS - 3.x","titleTemplate":false,"description":"Определение свойства options, используемого в различных определениях.","frontmatter":{"subtitle":"Определение свойства options, используемого в различных определениях."},"headers":[{"level":2,"title":"Массивы опций","slug":"массивы-опции","link":"#массивы-опции","children":[]},{"level":2,"title":"Предустановки опций","slug":"предустановки-опции","link":"#предустановки-опции","children":[]},{"level":2,"title":"Методы опций","slug":"методы-опции","link":"#методы-опции","children":[{"level":3,"title":"Детализированные определения опций","slug":"детализированные-определения-опции","link":"#детализированные-определения-опции","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}]}],"relativePath":"3.x/ru/element/define-options.md","filePath":"3.x/ru/element/define-options.md"}'),r={name:"3.x/ru/element/define-options.md"};function d(u,n,g,k,h,m){const t=s("pre-heading"),e=s("post-heading");return p(),l("div",null,[a(t),n[0]||(n[0]=c("h1",null,"Определение опций",-1)),a(e),n[1]||(n[1]=i(`<p>Часто вы можете встретить свойство <strong>options</strong>, <strong>optionsMethod</strong> или <strong>optionsPreset</strong> — эта статья описывает более подробно, как настраивать опции.</p><h2 id="массивы-опции"><a href="#массивы-опции" class="header-anchor">#</a> Массивы опций</h2><p>Свойство <code>options</code> должно указывать опции непосредственно как часть определения в виде пар ключ-значение, где значение и метка задаются независимо.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">draft</span><span class="token punctuation">:</span> Draft
    <span class="token key atrule">published</span><span class="token punctuation">:</span> Published
    <span class="token key atrule">archived</span><span class="token punctuation">:</span> Archived
</code></pre></div><p>Ключами могут быть целые числа с их меткой.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">1</span><span class="token punctuation">:</span> Simple
    <span class="token key atrule">2</span><span class="token punctuation">:</span> Complex
</code></pre></div><p>В дополнение к простым массивам, некоторые поля, такие как <a href="./form/field-radio.html">радио-списки</a>, поддерживают указание описания как части значений <code>options</code>. В этом случае значение определяется как другой массив с синтаксисом <code>key: [label, description]</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">all</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>All<span class="token punctuation">,</span> Guests and customers will be able to access this page.<span class="token punctuation">]</span>
    <span class="token key atrule">registered</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Registered only<span class="token punctuation">,</span> Only logged in member will be able to access this page.<span class="token punctuation">]</span>
    <span class="token key atrule">guests</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Guests only<span class="token punctuation">,</span> Only guest users will be able to access this page.<span class="token punctuation">]</span>
</code></pre></div><p>Другие поля, такие как <a href="./form/field-dropdown.html">выпадающие списки</a>, поддерживают указание иконки, изображения или цвета как части значений <code>options</code>. Если второй элемент массива начинается с <code>#</code>, он считается цветом, если значение содержит <code>.</code> — изображением, в противном случае — классом иконки.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">options</span><span class="token punctuation">:</span>
    <span class="token key atrule">red</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Color<span class="token punctuation">,</span> <span class="token string">&#39;#ff0000&#39;</span><span class="token punctuation">]</span>
    <span class="token key atrule">icon</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Icon<span class="token punctuation">,</span> <span class="token string">&#39;oc-icon-calendar&#39;</span><span class="token punctuation">]</span>
    <span class="token key atrule">image</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>Image<span class="token punctuation">,</span> <span class="token string">&#39;/path/to/image.png&#39;</span><span class="token punctuation">]</span>
</code></pre></div><h2 id="предустановки-опции"><a href="#предустановки-опции" class="header-anchor">#</a> Предустановки опций</h2><p>Свойство <code>optionsPreset</code> указывает код предустановки, который можно использовать для запроса доступных опций.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">optionsPreset</span><span class="token punctuation">:</span> icons
</code></pre></div><p>Доступны следующие предустановки:</p><div class="table"><table tabindex="0"><thead><tr><th>Предустановка</th><th>Описание</th></tr></thead><tbody><tr><td><strong>icons</strong></td><td>Список доступных имён иконок (например: <code>icon-calendar</code>)</td></tr><tr><td><strong>phosphorIcons</strong></td><td>Список доступных имён иконок (например: <code>ph ph-calendar</code>)</td></tr><tr><td><strong>locales</strong></td><td>Список доступных локалей (например: <code>en-au</code>)</td></tr><tr><td><strong>flags</strong></td><td>Список локалей с их иконками в виде флагов (например: <code>[en-au, flag-au]</code>)</td></tr><tr><td><strong>timezones</strong></td><td>Список доступных часовых поясов (например: <code>Australia/Sydney</code>)</td></tr></tbody></table></div><h2 id="методы-опции"><a href="#методы-опции" class="header-anchor">#</a> Методы опций</h2><p>Свойство <code>optionsMethod</code> указывает вызываемый PHP-метод, который можно использовать для запроса доступных опций. Обычно имя метода ссылается на метод, локальный для связанной модели.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> getMyOptionsFromModel
</code></pre></div><p>Имя метода также может быть статическим методом любого объекта.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">optionsMethod</span><span class="token punctuation">:</span> MyAuthor\\MyPlugin\\Helpers\\FormHelper<span class="token punctuation">:</span><span class="token punctuation">:</span>getMyStaticMethodOptions
</code></pre></div><h3 id="детализированные-определения-опции"><a href="#детализированные-определения-опции" class="header-anchor">#</a> Детализированные определения опций</h3><p>Внутри метода можно использовать детализированное определение для указания более расширенных опций, например, для установки индивидуальных атрибутов для каждой опции. Детализированное определение идентифицируется по его структуре ассоциативного массива.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getDetailedFieldOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token number">1</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 1&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option one&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token number">2</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 2&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option two&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;disabled&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Где возможно, поддерживаются следующие свойства:</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя при отображении опции пользователю.</td></tr><tr><td><strong>comment</strong></td><td>размещает описательный комментарий под меткой опции.</td></tr><tr><td><strong>readOnly</strong></td><td>определяет, является ли опция только для чтения.</td></tr><tr><td><strong>disabled</strong></td><td>определяет, отключена ли опция.</td></tr><tr><td><strong>hidden</strong></td><td>определяет опцию без её отображения.</td></tr><tr><td><strong>color</strong></td><td>определяет цвет индикатора состояния для опции в виде hex-цвета (dropdown)</td></tr><tr><td><strong>icon</strong></td><td>определяет имя иконки для этой опции (dropdown)</td></tr><tr><td><strong>image</strong></td><td>определяет URL изображения для этой опции (dropdown)</td></tr><tr><td><strong>optgroup</strong></td><td>установите в <code>true</code>, если дочерние элементы должны принадлежать структуре группы опций, по умолчанию: <code>false</code> (dropdown)</td></tr><tr><td><strong>children</strong></td><td>определяет дочерние опции как другой массив для вложенной структуры (checkbox list)</td></tr></tbody></table></div><p>Используйте свойство <code>children</code>, если определение опции поддерживает вложенность. Обычно это отображает структуру для списков чекбоксов и реализует группу опций для выпадающих списков.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getDetailedFieldOptions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token number">1</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 1&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option one&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;children&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token number">2</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Option 2&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is option two&#39;</span><span class="token punctuation">,</span>
                <span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token comment">// ...</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./form/field-checkboxlist.html">Поле Checkbox List</a></li><li><a href="./form/field-dropdown.html">Поле Dropdown</a></li><li><a href="./form/field-radio.html">Поле Radio</a></li></ul></div>`,29))])}const b=o(r,[["render",d]]);export{f as __pageData,b as default};
